	"gno.land/p/demo/svg"
	"gno.land/p/moul/md"
	ntavl "gno.land/p/nt/avl/v0" // svg.Canvas.Style is a *nt/avl/v0.Tree — keep that ABI at the svg boundary
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/samcrew/avl"
	"gno.land/p/samcrew/avl/pager"
