	membersMajority := daocond.MembersThreshold(0.1, memberStore.IsMember, memberStore.MembersCount)

	localDAO, daoPrivate = basedao.New(&basedao.Config{
		Name:             "Demo DAOKIT DAO",
		Description:      "This is a demo DAO built with DAOKIT",
		Members:          memberStore,
		InitialCondition: membersMajority,
		GetProfileString: profile.GetStringField,
		SetProfileString: profile.SetStringField,
		PrivateVarName:   "daoPrivate",
		RenderFn: func(path string, dao *basedao.DAOPrivate) string {
			s := ""
			if path == "" {
				s += renderDemo()
			}
			s += " \n\n--- \n\n "
			s += dao.RenderRouter.Render(path)
			s += "# My blog\n"
			s += myblog.Render()
			return s
		},
		SetImplemFn: setImplem,
	}, cur)

	// Create a new custom resource
	resource := daokit.Resource{
		Handler:     NewPostHandler(&myblog),
		Condition:   membersMajority,
		DisplayName: "Create Blog Post",
		Description: "Allows DAO members to create and publish new blog posts",
	}
	// Add it to our DAO
	daoPrivate.Core.Resources.Set(&resource)

	// Add some demo blog post proposals to showcase custom resource
	initBlogProposals()
}

// Propose creates a new proposal
// To execute this function, you must use a MsgRun (maketx run)
// See why it is necessary in Gno Documentation: https://docs.gno.land/users/interact-with-gnokey#run
func Propose(cur realm, req daokit.ProposalRequest) {
	localDAO.Propose(req, cur)
}

// Vote allows DAO members to cast their vote on a specific proposal
func Vote(cur realm, proposalID uint64, vote daocond.Vote) {
	localDAO.Vote(proposalID, vote, cur)
}

// Execute triggers the implementation of a proposal's actions
func Execute(cur realm, proposalID uint64) {
	localDAO.Execute(proposalID, cur)
}

// Render generates a UI representation of the DAO's state
func Render(path string) string {
	return localDAO.Render(path)
}

// Updates the DAO implementation when governance proposals change it.
// This allows the DAO to upgrade itself through proposals that modify its core logic.
func setImplem(newLocalDAO daokit.DAO) {
	localDAO = newLocalDAO
}

package custom_resource

import (
	"gno.land/p/mason/md"
	"gno.land/p/moul/txlink"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/samcrew/daokit"
)

// initBlogProposals creates initial blog post proposals to demonstrate custom resource functionality
func initBlogProposals() {
	blogPosts := []struct {
		title    string
		content  string
		proposer string
	}{
		{"Welcome to our DAO Blog", "This is our first blog post created through DAO governance!", "g1demo1234567890abcdefghijklmnopqrstuvw1"},
		{"Custom Resources in Action", "This post demonstrates how custom resources work in daokit. Any custom action can be proposed and voted on!", "g1demo1234567890abcdefghijklmnopqrstuvw2"},
		{"Community Updates", "Regular updates from our DAO community will be posted here through democratic proposals.", "g1demo1234567890abcdefghijklmnopqrstuvw3"},
	}

	for _, post := range blogPosts {
		// Calling the custom action
		action := NewPostAction(post.title, post.content)

		req := daokit.ProposalRequest{
			Title:       ufmt.Sprintf("Create blog post: %s", post.title),
			Description: ufmt.Sprintf("This proposal will create a new blog post."),
			Action:      action,
		}
		daoPrivate.Core.Propose(post.proposer, req)
	}
}

// Bypass limitation by adding yourself to the DAO.
// It is necessary to be part of the DAO to create a Proposal.
func AddMember(cur realm) {
	// Safe here only because cur is THIS realm's own, minted by this crossing
	// function. CallerID is not the entry-point gate: copied somewhere that
	// passes a realm it received from elsewhere, this becomes the donation bug
	// the DAO entry points exist to refuse. If you need the gate, go through
	// Propose/Vote/Execute.
	id := daoPrivate.CallerID(daoPrivate, cur)
	daoPrivate.Members.AddMember(id, make([]string, 0))
}

// Creates a Proposal to create a new blog post.
// This demonstrates the custom resource functionality of the DAO.
// Parameters:
//   - title: The title of the blog post
//   - content: The content of the blog post
func ProposeNewPost(cur realm, title, content string) {
	// Calling the custom action
	action := NewPostAction(title, content)

	req := daokit.ProposalRequest{
		Title:       ufmt.Sprintf("Create new blog post: %s", title),
		Description: ufmt.Sprintf("This proposal will create a new blog post with title '%s' and content: %s", title, content),
		Action:      action,
	}
	Propose(cur, req)
}

func renderDemo() string {
	s := ""
	s += "# 🔧 Custom Resource Demo\n\n"
